ruleHooks.extraMethods:
; Carregar um pedido na global de trabalho do monitor (aplica os filtros)
; linha = número^pedConsistem^status^data^cliente^descrição^valor^entrega^PDF^NF^codPedido
;
; set sc=$$CarregarPedidoMonitor^WDOMTESTEPV100RG(term,codEmpresa,codPedido,dataInicial,dataFinal,.tabStatus,pedidoConsistem,pedidoRepresentante,cliente)
CarregarPedidoMonitor(term,codEmpresa,codPedido,dataInicial,dataFinal,tabStatus,pedidoConsistem,pedidoRepresentante,cliente)	;
$$$VAR
new sc,dados,dadosCliente,linha,status
;
set dados=$get(^WDOMTESTEPVPD(1,codEmpresa,1,codPedido))
quit:dados="" $$$OK
set status=$piece(dados,Z,3)
if $get(dataInicial)'="",$piece(dados,Z,6)<dataInicial quit $$$OK
if $get(dataFinal)'="",$piece(dados,Z,6)>dataFinal quit $$$OK
if $data(tabStatus),'$data(tabStatus(status)) quit $$$OK
if $get(pedidoConsistem)'="",$piece(dados,Z,4)'=pedidoConsistem quit $$$OK
if $get(pedidoRepresentante)'="",codPedido'=pedidoRepresentante quit $$$OK
if $get(cliente)'="",$piece(dados,Z,7)'=cliente quit $$$OK
;
set sc=$$ObterDadosCliente^WDOMTESTEPV100ARG(codEmpresa,codPedido,$piece(dados,Z,7),.dadosCliente)
set linha=$$NumeroPedido^WDOMTESTEPV100ARG(codEmpresa,codPedido)
set linha=linha_Z_$piece(dados,Z,4)_Z_$$DescricaoStatus^WDOMTESTEPV100ARG(status)
set linha=linha_Z_$piece(dados,Z,6)_Z_$piece(dados,Z,7)_Z_$piece($get(dadosCliente),Z,1)
set linha=linha_Z_$fnumber($$ValorTotalPedido^WDOMTESTEPV100ARG(codEmpresa,codPedido),".",2)_Z_$piece(dados,Z,9)
set linha=linha_Z_"PDF"_Z_$select($piece(dados,Z,4)'="":"Nota Fiscal",1:"")_Z_codPedido_Z_status_Z_$$NomeRepresentante(codEmpresa,$piece(dados,Z,5))
;
quit $$GravarGlobalTrabalho(term,codPedido,linha)
;
; Nome do representante (código - nome)
;
; set nome=$$NomeRepresentante^WDOMTESTEPV100RG(codEmpresa,codRepresentante)
NomeRepresentante(codEmpresa,codRepresentante)	;
$$$VAR
new sc,ftre
;
if $get(codRepresentante)="" quit ""
set sc=$$VerRepresentante^CCFTRG001(codEmpresa,codRepresentante,.ftre)
;
quit codRepresentante_" - "_$piece($get(ftre),Z,1)
;
; Indeferir (tela de justificativa)
;
; set sc=$$IndeferirPedido^WDOMTESTEPV100RG(codEmpresa,codPedido,observacao)
IndeferirPedido(codEmpresa,codPedido,observacao)	;
$$$VAR
;
quit $$IndeferirPedido^WDOMTESTEPV100ARG(codEmpresa,codPedido,$get(observacao))
;
; Usuário pode enviar/indeferir? (comercial = admin na configuração)
;
; set admin=$$UsuarioAdmin^WDOMTESTEPV100RG(codEmpresa)
UsuarioAdmin(codEmpresa)	;
$$$VAR
new sc,admin,tabRepresentante
;
set sc=$$ObterConfigUsuario^WDOMTESTEPV100ARG(codEmpresa,$$VEROP^%CSUTIUD(1),.admin,.tabRepresentante)
;
quit +$get(admin)
;
; Notas fiscais do pedido Consistem (opções para o %CSUTIMB): "NF1;NF2"
;
; set sc=$$ObterNotasPedido^WDOMTESTEPV100RG(codEmpresa,codPedidoConsistem,.opcoes,.tabNotas)
ObterNotasPedido(codEmpresa,codPedidoConsistem,opcoes,tabNotas)	;
$$$VAR
;
set opcoes=""
kill tabNotas
new dataEmissao,codNota,quantidade
;
if $get(codPedidoConsistem)="" quit $$$ERROR(10000,"Pedido ainda não foi enviado para o Consistem!")
set (dataEmissao,quantidade)=""
for  set dataEmissao=$order(^PVNF(codEmpresa,codPedidoConsistem,dataEmissao)) quit:dataEmissao=""  do
. set codNota=""
. for  set codNota=$order(^PVNF(codEmpresa,codPedidoConsistem,dataEmissao,codNota)) quit:codNota=""  do
. . set quantidade=quantidade+1
. . set tabNotas(quantidade)=dataEmissao_Z_codNota
. . set opcoes=opcoes_$select(opcoes="":"",1:";")_"NF "_codNota_" ("_$zdate(dataEmissao,4)_")"
if 'quantidade quit $$$ERROR(10000,"Nenhuma nota fiscal para o pedido "_codPedidoConsistem_"!")
;
quit $$$OK
;
; Boleto do pedido: 2ª via dos boletos da primeira NF (PDF para download)
;
; set sc=$$BaixarBoletoPedido^WDOMTESTEPV100RG(codEmpresa,codPedidoConsistem)
BaixarBoletoPedido(codEmpresa,codPedidoConsistem)	;
$$$VAR
new sc,opcoes,tabNotas,codNota,codCliente,ftcl,objBoleto,paramDownload
;
set sc=$$ObterNotasPedido(codEmpresa,$get(codPedidoConsistem),.opcoes,.tabNotas)
if $$$ISERR(sc) quit sc
set codNota=$piece(tabNotas(1),Z,2)
set codCliente=$piece($get(^PVPD(codEmpresa,codPedidoConsistem)),Z,1)
set sc=$$VerCliente^CCFTRG001(codEmpresa,codCliente,.ftcl)
if $$$ISERR(sc) quit sc
;
set sc=$$ObterSegundaViaBoletoApi^CCCCRG001API(codEmpresa,$piece(ftcl,Z,7),codNota,"","",.objBoleto)
if $$$ISERR(sc) quit sc
if '$isobject($get(objBoleto)) quit $$$ERROR(10000,"Boleto não encontrado para a nota "_codNota_"!")
;
set paramDownload=##class(%ZEN.proxyObject).%New()
set paramDownload.nomeArquivo="Boleto_NF_"_codNota_".pdf"
;
quit $$Download^%CSW1DOWNLOAD(objBoleto.arquivo,paramDownload)
